import numpy as np

def _preserving_call(function, *arguments):
    snapshots = [(argument, argument.copy()) for argument in arguments if isinstance(argument, np.ndarray)]
    result = function(*arguments)
    for argument, before in snapshots:
        if not np.array_equal(argument, before):
            raise AssertionError("The function mutated an input array.")
    return result
assert np.allclose(_dense_expansion(_preserving_call(rotate_and_project_expansion, x.copy(), 5, 0.37, 2, 0.03, 2), 2), target)

